      applied_by: { cve: string; pr: string; number: number; trace_id: string; run_id: string }[];
    };
  };
  backtest: Record<'v1' | 'v2', {
    cases: number;
    decided: number;
    accuracy: number;
    false_not_affected: number;
    false_affected: number;
    unproven: number;
    escalation_rate: number;
    usd_per_case: number;
    false_not_affected_cves: string[];
  }>;
  detections: { name: string; hits: number }[];
  detection_check: { name: string; run_id: string; trace_id: string; at: string; confirmed: boolean; hits_after: number };
  economics: {
    inputs: { name: string; base: string; bear: string; bull: string; status: string }[];
    pages: { name: string; url: string }[];
    results: { name: string; base: string; bear: string; bull: string }[];
    plan: string;
  };
  finding?: Finding;
  method: {
    example: { cve: string; anchor: string; pr: string; number: number };
    issue: { cve: string; anchor: string; url: string; number: number };
    code: Record<'locate' | 'probe' | 'calibrate' | 'verify' | 'decide', string>;
    evidence: string;
  };
  limits: { restarts: number; recovery: { cve: string; run_id: string; url: string } };
  files: Record<'detections' | 'detections_flag_check' | 'results' | 'results_live' | 'entire_docs' | 'evidence_md', string>;
  links: { prs: string[]; issues: string[] };
}

export interface Gate {
  id: string;
  ok: boolean;
  detail?: string;
  reason?: string;
}

export interface RunSummary {
  outcomes: string[];
  failing_ids: string[];
}

export interface ReceiptCell {
  line: LineId;
  verdict: MatrixVerdict;
  reason?: string;
  detail?: string;
  gates: Gate[];
  probe?: { origin: 'porter' | 'hand-written'; sha: string };
  fix?: { series: string; commits: string[]; um: string };
  runs: Partial<Record<'um' | 'up' | 'lt', RunSummary>>;
}

export interface Receipt {
  cve: string;
  cells: ReceiptCell[];
  matrix_logs?: string;
}

import { prNum, site } from '@/lib/site';
import { Section } from './Section';

/** How a verdict is earned: the rule, then five numbered stages with the artifact behind each. */
export function Method() {
  const s = site.summary;
  const m = site.method;
  const f = site.finding;
  const q = site.query;
  const stages: { name: string; text: React.ReactNode; proof: React.ReactNode }[] = [
    {
      name: 'Locate the fix',
      text: 'Find the upstream commit that fixed the CVE on a supported branch, with its message and its test changes.',
      proof: (
        <>
          {f && (
            <>
              <a className="link font-mono text-[0.9em]" href={f.fix_url}>
                {f.fix_commit.slice(0, 10)}
              </a>{' '}
              for {f.cve} ·{' '}
            </>
          )}
          <a className="link" href={m.code.locate}>
            locate.py
          </a>
        </>
      ),
    },
    {
      name: 'Write an independent probe',
      text: 'A porter model writes a test from the advisory and upstream’s test diff. It never sees the fix’s code hunks.',
      proof: (
        <>
          The probe&rsquo;s sha in every receipt ·{' '}
          <a className="link" href={m.code.probe}>
            probe.py
          </a>
        </>
      ),
    },
    {
      name: 'Calibrate on upstream',
      text: `The probe must fail ×${s.probe_before} before the fix and pass ×${s.probe_after} after it, its coverage must reach the code the fix changes, and a rebuilt vulnerability must be caught.`,
      proof: (
        <>
          The calibration triangle in each receipt, e.g.{' '}
          <a className="link whitespace-nowrap" href={`#${m.example.anchor}`}>
            {m.example.cve}
          </a>{' '}
          ·{' '}
          <a className="link" href={m.code.calibrate}>
            calibrate.py
          </a>
        </>
      ),
    },
    {
      name: 'Adapt and verify on the old line',
      text: 'Port the fix to 4.2. There the probe must go from fail to pass, and Django’s own tests must show no new failures.',
      proof: (
        <>
          {s.fail_to_pass} of {s.prs} PRs FAIL ×{s.probe_before} → PASS ×{s.probe_after}:{' '}
          <a className="link" href={m.evidence}>
            campaign_evidence.json
          </a>{' '}
          ·{' '}
          <a className="link" href={m.code.verify}>
            verify.py
          </a>
        </>
      ),
    },
    {
      name: 'Decide and publish',
      text: 'A verified port becomes a candidate backport PR with a claim table. What it cannot prove becomes an evidence issue. When a choice is real, it asks the owner once.',
      proof: (
        <>
          <a className="link" href={m.example.pr}>
            PR {prNum(m.example.pr)}
          </a>{' '}
          ·{' '}
          <a className="link" href={m.issue.url}>
            evidence {prNum(m.issue.url)}
          </a>{' '}
          ·{' '}
          <a className="link" href={q.issue}>
            question {prNum(q.issue)}
          </a>{' '}
          ·{' '}
          <a className="link" href={m.code.decide}>
            decide.py
          </a>
        </>
      ),
    },
  ];
  return (
    <Section id="method" title="Method — how a verdict is earned.">
      <p className="mt-8 max-w-[22ch] text-[2.4rem] leading-[1.08] tracking-[-0.02em] md:text-[3.4rem]">
        Never trust a test that hasn&rsquo;t failed.
      </p>
      <ol className="mt-10 grid border-t border-rule">
        {stages.map((st, i) => (
          <li key={st.name} className="grid gap-x-8 gap-y-1 border-b border-rule py-5 md:grid-cols-12">
            <p className="font-mono text-sm tabular-nums text-muted md:col-span-1">{String(i + 1).padStart(2, '0')}</p>
            <h3 className="text-xl leading-snug md:col-span-3">{st.name}</h3>
            <div className="md:col-span-8">
              <p className="max-w-measure">{st.text}</p>
              <p className="mt-1 text-[0.95rem] text-muted">
                <span className="label mr-2">Artifact</span>
                {st.proof}
              </p>
            </div>
          </li>
        ))}
      </ol>
    </Section>
  );
}
import { prNum, site } from '@/lib/site';
import { Nb, Section, Stamp } from './Section';

/** The conservator's query: question #6, the wait, the answer, precedent P001 and its reuse. */
export function Query() {
  const q = site.query;
  const p = q.precedent;
  const applied = (cve: string) => p.applied_by.find((a) => a.cve === cve);
  const own = applied(q.asked_by);
  const reused = p.applied_by.filter((a) => a.cve !== q.asked_by);
  const conn = site.connector;
  const connRow = conn && site.rows.find((r) => r.cve === conn.from);
  const Trace = ({ id }: { id: string }) => (
    <span className="font-mono text-[0.72rem] text-muted [overflow-wrap:anywhere]">trace {id}</span>
  );
  const steps: { when?: string; title: React.ReactNode; detail?: React.ReactNode }[] = [
    {
      when: q.asked_at,
      title: (
        <>
          <Nb>{q.asked_by}</Nb> opens{' '}
          <a className="link" href={q.issue}>
            question {prNum(q.issue)}
          </a>
          .
        </>
      ),
      detail: (
        <>
          <span className="font-mono text-[0.8rem]">{p.kind}</span>: upstream&rsquo;s fix rewrote existing 4.2 tests in the
          same commit, so the verified backport makes them fail. Adopt upstream&rsquo;s test changes, or not? That is the
          owner&rsquo;s call, not the agent&rsquo;s. {q.asking_trace && <Trace id={q.asking_trace} />}
        </>
      ),
    },
    ...q.waited.map((cve) => ({
      title: (
        <>
          <Nb>{cve}</Nb> hits the same kind of choice and waits on {prNum(q.issue)} instead of asking again.
        </>
      ),
    })),
    {
      title: (
        <>
          The owner answers{' '}
          <a className="link" href={q.issue}>
            <code className="whitespace-nowrap font-mono text-[0.9em]">{p.answer}</code>
          </a>
          .
        </>
      ),
    },
    {
      when: p.stored_at,
      title: <>Precedent {p.id} is stored: next time, the same kind of choice gets the same answer without asking.</>,
    },
    ...(own
      ? [
          {
            title: (
              <>
                <a className="link" href={own.pr}>
                  {prNum(own.pr)}
                </a>{' '}
                applies it (<Nb>{own.cve}</Nb>).
              </>
            ),
            detail: <Trace id={own.trace_id} />,
          },
        ]
      : []),
    ...reused.map((a) => ({
      title: (
        <>
          <a className="link" href={a.pr}>
            {prNum(a.pr)}
          </a>{' '}
          reuses it without asking (<Nb>{a.cve}</Nb>).
        </>
      ),
      detail: <Trace id={a.trace_id} />,
    })),
    ...(conn && connRow
      ? [
          {
            title: (
              <>
                <a className="link" href={connRow.campaign.link}>
                  #{conn.pr}
                </a>{' '}
                (<Nb>{conn.from}</Nb>) is stacked on #{conn.on}: its upstream fix rewrites lines that <Nb>{conn.to}</Nb>&rsquo;s fix introduced.
              </>
            ),
            detail: connRow.campaign.traces?.[0] ? <Trace id={connRow.campaign.traces[0]} /> : undefined,
          },
        ]
      : []),
  ];
  return (
    <Section
      id="query"
      title="The conservator’s query."
      lede={`One question in ${site.summary.cves} advisories, asked once and answered once. The answer became policy.`}
    >
      <ol className="relative mt-10 grid max-w-[52rem] gap-7 border-l border-rule pl-8 md:ml-[8.333%]">
        {steps.map((s, i) => (
          <li key={i} className="relative">
            <span
              aria-hidden
              className="absolute -left-8 top-[0.45rem] h-2.5 w-2.5 -translate-x-1/2 rounded-full border border-ink bg-paper"
            />
            <p className="flex flex-wrap items-baseline gap-x-3">
              <span className="font-mono text-[0.75rem] tabular-nums text-muted">{String(i + 1).padStart(2, '0')}</span>
              {s.when && <Stamp iso={s.when} />}
            </p>
            <p className="mt-0.5 text-[1.1rem] leading-snug">{s.title}</p>
            {s.detail && <p className="mt-1 max-w-measure text-[0.95rem] text-muted">{s.detail}</p>}
          </li>
        ))}
      </ol>
    </Section>
  );
}

