import { cn } from '@/lib/utils';

/** A report section: a fine rule above, an h2, then the body on the 12-column grid. */
export function Section({
  id,
  title,
  lede,
  children,
  className,
}: {
  id: string;
  title: React.ReactNode;
  lede?: React.ReactNode;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <section id={id} aria-labelledby={`${id}-h`} className={cn('mt-20 border-t border-rule pt-10 md:mt-24', className)}>
      <header className="grid gap-2 md:grid-cols-12">
        <h2 id={`${id}-h`} className="text-3xl leading-tight md:col-span-9 md:text-4xl">
          {title}
        </h2>
        {lede && <p className="max-w-measure text-lg text-muted md:col-span-8">{lede}</p>}
      </header>
      {children}
    </section>
  );
}

/** The section break between parts of the report. */
export function Asterism() {
  return (
    <p aria-hidden className="asterism mt-20 text-center font-mono text-sm tracking-[0.6em] text-muted md:mt-24">
      * * *
    </p>
  );
}

/** "Oct 11 2026 · 21:20Z" from an ISO timestamp */
export function Stamp({ iso, time = true }: { iso: string; time?: boolean }) {
  const M = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const [y, m, d] = iso.slice(0, 10).split('-').map(Number);
  const hm = iso.length > 10 ? iso.slice(11, 16) : '';
  return (
    <time dateTime={iso} className="font-mono text-[0.75rem] tabular-nums text-muted">
      {M[(m ?? 1) - 1]} {d} {y}
      {time && hm && ` · ${hm}Z`}
    </time>
  );
}

/** Keeps an identifier (CVE id, version) on one line inside prose. */
export function Nb({ children }: { children: React.ReactNode }) {
  return <span className="whitespace-nowrap">{children}</span>;
}

/** Typesetting only: straight apostrophes to curly ones (the words stay verbatim). */
export const curly = (s: string) => s.replace(/(\w)'(\w)/g, '$1’$2');
export const MAIN_CLASS = 'relative';
/** The content column for v2 sections. */
export const WRAP = 'mx-auto w-full max-w-[90rem] px-5 md:px-10';
import data from '@/data/site.json';
import type { Chip, Line, LineId, Row, Site } from '@/data/types';

export const site = data as unknown as Site;
export const lineById = Object.fromEntries(site.lines.map((l) => [l.id, l])) as Record<LineId, Line>;
export const rowByAnchor = new Map<string, Row>(site.rows.map((r) => [r.anchor, r]));

export const CHIP_META: Record<Chip, { word: string; symbol: string; cls: string; meaning: string }> = {
  FIX_READY: { word: 'Fix ready', symbol: '✓', cls: 'bg-fix-bg text-fix-fg border-fix-fg/25', meaning: 'affected, and a verified candidate backport is open' },
  NOT_AFFECTED: { word: 'Not affected', symbol: '○', cls: 'bg-na-bg text-na-fg border-na-fg/25', meaning: 'proven not affected by a calibrated probe' },
  UNPROVEN: { word: 'Unproven', symbol: '?', cls: 'bg-unp-bg text-unp-fg border-unp-fg/25', meaning: 'the probe could not decide; evidence filed' },
  AFFECTED: { word: 'Affected', symbol: '!', cls: 'bg-aff-bg text-aff-fg border-aff-fg/25', meaning: 'the calibrated probe fails on this line' },
  NO_PROBE: { word: 'No probe', symbol: '–', cls: 'bg-np-bg text-np-fg border-np-fg/25', meaning: 'no probe passed calibration' },
};

export const REASONS: Record<string, string> = {
  NO_REACH: 'the probe never reached the code the fix changes on this line',
  NON_DISCRIMINATING: 'no probe failed before the fix and passed after it',
  PROBE_ERROR: 'the probe could not be made to run cleanly',
  MUTANT_UNBUILDABLE: 'the vulnerability could not be rebuilt inside this line to check the probe catches it',
  MUTANT_SURVIVED: 'a rebuilt vulnerability was not caught by the probe',
  FLAKY: 'the probe gave different results across runs',
  FAIL_MISMATCH: 'the probe failed on this line with different test ids than before the fix',
  STRUCTURAL_TEST: 'upstream tests error before the fix, so they cannot serve as the probe',
  ENV_SKIP: 'the probe needs a backend this harness does not run',
  ALREADY_PUBLISHED: 'published earlier by the first end-to-end run; no new PR',
};

export const GATES: Record<string, string> = {
  C0: 'Upstream tests fail before the fix and pass after it',
  C1: 'Probe fails on U⁻ with stable test ids, passes on U⁺',
  C2: 'Probe runs cleanly on this line',
  C3: 'Coverage reaches the code the fix changes',
  C4ab: 'A rebuilt vulnerability on this line is caught',
  C4c: 'The vulnerable lines were never on this line (provenance)',
  absent: 'The fixed symbol does not exist on this line',
};

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
/** 2026-08-04 → "Aug 4 2026" */
export function shortDate(iso: string) {
  const [y, m, d] = iso.slice(0, 10).split('-').map(Number);
  return `${MONTHS[(m ?? 1) - 1]} ${d} ${y}`;
}
/** 2026-04-07 → "7 April 2026" */
export function longDate(iso: string) {
  const full = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const [y, m, d] = iso.slice(0, 10).split('-').map(Number);
  return `${d} ${full[(m ?? 1) - 1]} ${y}`;
}
export const prNum = (url: string) => `#${url.split('/').pop()}`;
import { useState } from 'react';
import { Check, Copy } from 'lucide-react';

export function CopyButton({ value, label }: { value: string; label: string }) {
  const [done, setDone] = useState(false);
  return (
    <button
      type="button"
      className="press inline-flex h-10 w-10 shrink-0 items-center justify-center rounded-chip text-muted hover-ink"
      aria-label={done ? `${label} copied` : `Copy ${label}`}
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(value);
          setDone(true);
          window.setTimeout(() => setDone(false), 1500);
        } catch {
          /* clipboard blocked: the value stays selectable on the page */
        }
      }}
    >
      {done ? <Check className="h-4 w-4" aria-hidden /> : <Copy className="h-4 w-4" aria-hidden />}
    </button>
  );
}
import { useRef } from 'react';
import { m, useReducedMotion, useScroll, useTransform } from 'motion/react';
import { longDate, site } from '@/lib/site';
import { WRAP } from '@/lib/layout';
import { Photo } from './Photo';

const MONTH = longDate(site.eol).split(' ')[1];
const ORIGIN: Record<string, string> = { eval: 'the last upstream release', distro: 'still shipping' };

/** Beat 2, "It examines every part": a full-bleed macro photograph, the statement, the version plates. */
export function Examines() {
  const ref = useRef<HTMLElement>(null);
  const reduce = useReducedMotion();
  const { scrollYProgress } = useScroll({ target: ref, offset: ['start end', 'end start'] });
  const y = useTransform(scrollYProgress, [0, 1], ['-12%', '12%']);
  return (
    <section ref={ref} id="examines" aria-labelledby="examines-h" className="relative isolate overflow-hidden py-28 md:py-44">
      <m.div aria-hidden className="absolute inset-x-0 -inset-y-[14%] -z-10" style={reduce ? undefined : { y }}>
        <Photo name="movement" sizes="100vw" className="h-full w-full" />
        <div className="absolute inset-0 bg-gradient-to-b from-paper via-paper/40 to-paper" />
        <div className="absolute inset-0 bg-gradient-to-r from-paper/90 via-paper/30 to-transparent" />
      </m.div>
      <div className={WRAP}>
        <p className="eyebrow">It examines every part</p>
        <h2 id="examines-h" className="display mt-5 max-w-[16ch] text-[clamp(2.6rem,6.4vw,6rem)]">
          Django stopped patching 4.2 in {MONTH}. <em className="italic text-brass-hi">Debian and Ubuntu still ship it.</em>
        </h2>
        <p className="mt-6 max-w-[38rem] text-lg text-ink/80">
          Django published {site.summary.cves} security advisories after 4.2&rsquo;s end of life on {longDate(site.eol)}. Heirloom
          checked each one on the three 4.2 release lines people still run.
        </p>
        <ul className="mt-12 grid max-w-[60rem] gap-4 md:grid-cols-3" aria-label="The three release lines">
          {site.lines.map((l, i) => (
            <m.li
              key={l.id}
              className="plate relative rounded-[10px] px-5 py-4"
              initial={{ opacity: 0, x: -40 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true, margin: '-10% 0px' }}
              transition={{ duration: 0.9, ease: [0.23, 1, 0.32, 1], delay: 0.15 + i * 0.14 }}
            >
              <span aria-hidden className="absolute right-4 top-4 h-1.5 w-1.5 rounded-full bg-brass/70 shadow-[0_0_0_3px_rgb(var(--brass)/0.15)]" />
              <span aria-hidden className="absolute bottom-4 right-4 h-1.5 w-1.5 rounded-full bg-brass/70 shadow-[0_0_0_3px_rgb(var(--brass)/0.15)]" />
              <p className="label">
                {l.abbr} · {l.name} {l.note !== 'upstream' && `(${l.note})`}
              </p>
              <p className="engraved mt-2 break-all font-mono text-[1.15rem] leading-tight md:text-[1.05rem] xl:text-[1.2rem]">{l.version}</p>
              <p className="mt-2 text-sm text-muted">{ORIGIN[l.kind] ?? ''}</p>
            </m.li>
          ))}
        </ul>
      </div>
    </section>
  );
}

