/** Renders RST ``literal`` spans from advisory titles in mono, with break points after . and _ */
export function RstTitle({ text }: { text: string }) {
  const parts = text.replace(/\.$/, '').split('``');
  return (
    <>
      {parts.map((p, i) =>
        i % 2 ? (
