            <Breakable text={p} />
          </code>
        ) : (
          <span key={i}>{p}</span>
        ),
      )}
    </>
  );
}

/** A long identifier with break opportunities after . and _ (never mid-word). */
export function Breakable({ text }: { text: string }) {
  return (
    <>
      {text.split(/(?<=[._])/).map((seg, j) => (
        <span key={j}>
          {j > 0 && <wbr />}
          {seg}
        </span>
      ))}
    </>
  );
}
